import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
import Page12 from './pages/Page12.jsx';
const pages={"demo-agency-1":Page0,"demo-agency-1-about":Page1,"demo-agency-1-article":Page2,"demo-agency-1-careers":Page3,"demo-agency-1-contact":Page4,"demo-agency-1-faq":Page5,"demo-agency-1-journal":Page6,"demo-agency-1-pricing":Page7,"demo-agency-1-project":Page8,"demo-agency-1-service":Page9,"demo-agency-1-services":Page10,"demo-agency-1-team":Page11,"demo-agency-1-work":Page12};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-agency-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-agency-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

